async function derivarChave(senha:string,sal:Uint8Array){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(senha),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:sal as BufferSource,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function cifrarBackup(texto:string,senha:string){const sal=crypto.getRandomValues(new Uint8Array(16));const iv=crypto.getRandomValues(new Uint8Array(12));const chave=await derivarChave(senha,sal);const cifrado=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},chave,new TextEncoder().encode(texto)));return JSON.stringify({formato:'ControlAI-Encrypted',versao:1,sal:Array.from(sal),iv:Array.from(iv),dados:Array.from(cifrado)});}
async function decifrarBackup(obj:Record<string,unknown>,senha:string){const sal=new Uint8Array(obj.sal as number[]);const iv=new Uint8Array(obj.iv as number[]);const dados=new Uint8Array(obj.dados as number[]);const chave=await derivarChave(senha,sal);return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv},chave,dados));}
