  useEffect(()=>{if(!isGestora||categoryMigrations.current.has(contaId))return;const needs=categorias.some(c=>c.tipo==='receita'&&c.nome==='Contribuições')||registros.some(e=>(e.gestao?.tipo==='contribuicao'&&e.categoria!=='Contribuição')||(['compraMercado','repasseMercado'].includes(e.gestao?.tipo??'')&&e.categoria!=='Mercado'))||recorrencias.some(r=>r.tipo==='receita'&&r.categoria==='Contribuições');if(!needs)return;categoryMigrations.current.add(contaId);normalizeGestoraCategories(db,contaId).catch(error=>console.error('Falha ao atualizar categorias da gestora',error)).finally(()=>categoryMigrations.current.delete(contaId));},[isGestora,contaId,categorias,registros,recorrencias]);
