  async function criarConta(e:React.FormEvent){e.preventDefault();const nome=nomeConta.trim();if(!nome)return;const id=editandoConta??crypto.randomUUID();try{await db.transaction([db.contas,db.categorias],async tx=>{const fresh=await tx.contas.get(id);if(editandoConta&&!fresh)throw Error('Conta não encontrada.');if(fresh&&tipoConta!=='casal'&&((fresh.distribuicoesCasal?.length??0)>0||(fresh.transferenciasPessoais?.length??0)>0))throw Error('Esta conta possui saldos pessoais. Preserve o tipo Casal para manter o histórico acessível.');if(fresh&&accountType(fresh)==='gestora'&&tipoConta!=='gestora'&&((fresh.pessoas?.length??0)>0||(fresh.mercados?.length??0)>0))throw Error('Esta conta possui pessoas ou mercados de gestão. Preserve o tipo Gestora para manter os acertos acessíveis.');if(fresh)await tx.contas.update(id,{nome,tipo:tipoConta,conjunta:tipoConta==='casal'});else{await tx.contas.add({id,nome,tipo:tipoConta,conjunta:tipoConta==='casal',padrao:contas.length===0});await tx.categorias.bulkAdd(categoriasIniciais(id));}});setNomeConta('');setTipoConta('solo');setEditandoConta(null);setAccountDialog(false);setContaId(id);}catch(reason){alert(reason instanceof Error?reason.message:'Não foi possível salvar.');}}
