  async function excluirConta(c:Conta){if(contas.length<=1){alert('Mantenha ao menos uma conta.');return;}if(!window.confirm(`Excluir a conta "${c.nome}" e TODOS os seus lançamentos, reservas, categorias, salários e recorrências? Esta ação é irreversível. Faça um backup antes.`))return;const proxima=contas.find(x=>x.id!==c.id&&x.padrao)??contas.find(x=>x.id!==c.id)!;await db.transaction([db.contas,db.lancamentos,db.configuracoes,db.reservas,db.categorias,db.recorrencias,db.salarios,db.fechamentos],async(tx)=>{await Promise.all([tx.fechamentos.where('contaId').equals(c.id).delete(),tx.lancamentos.where('contaId').equals(c.id).delete(),tx.reservas.where('contaId').equals(c.id).delete(),tx.categorias.where('contaId').equals(c.id).delete(),tx.recorrencias.where('contaId').equals(c.id).delete(),tx.salarios.where('contaId').equals(c.id).delete(),tx.configuracoes.where('contaId').equals(c.id).delete()]);await tx.contas.delete(c.id);if(c.padrao)await tx.contas.update(proxima.id,{padrao:true});});if(editandoConta===c.id){setEditandoConta(null);setNomeConta('');setTipoConta('solo');}if(contaId===c.id)setContaId(proxima.id);if(c.padrao)localStorage.setItem('controlai-conta-padrao',proxima.id);}
  async function concluirPrimeiroAcesso(e:React.FormEvent){e.preventDefault();const valores=Object.fromEntries(Object.entries(configInicial).map(([k,v])=>[k,paraCentavos(v||'0')]));if(Object.values(valores).some(v=>v<0||!Number.isSafeInteger(v))){alert('Informe valores válidos.');return;}const configurarRenda=Object.values(configInicial).some(v=>v.trim()!=='');const id=crypto.randomUUID();await db.transaction([db.contas,db.salarios,db.categorias],async(tx)=>{if(await tx.contas.count())return;await tx.contas.add({id,nome:tipoConta==='gestora'?'Conta gestora':contaConjunta?'Conta conjunta':'Minha conta',tipo:tipoConta,conjunta:tipoConta==='casal',padrao:true});await tx.categorias.bulkAdd(categoriasIniciais(id));if(configurarRenda&&tipoConta!=='gestora')await tx.salarios.put({id:`${id}:1`,contaId:id,titular:'Pessoa 1',liquido:valores.liquido,refeicao:valores.refeicao,beneficio:valores.beneficio,adicional:0});});setContaId(id);localStorage.setItem('controlai-conta-padrao',id);setOnboarding(false);setAba('inicio');}
