  function mudarMes(delta:number){const [y,m]=mes.split('-').map(Number);const d=new Date(y,m-1+delta,1);setMes(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);}
  const categoriasDisponiveis=(t:Tipo)=>{const cadastradas=categorias.filter(c=>c.tipo===t).map(c=>c.nome);const padrao=t==='receita'?categoriasReceita:categoriasDespesa;return categorias.length?cadastradas:padrao;};
  const categoriaDefinida=(nome:string,t:Tipo)=>categorias.find(c=>c.nome===nome&&c.tipo===t);
  useEffect(()=>{setSalarioForm({liquido:String((salario?.liquido??0)/100),refeicao:String((salario?.refeicao??0)/100),beneficio:String((salario?.beneficio??0)/100),adicional:String((salario?.adicional??0)/100)});},[salario]);
  const salarioBase=contaAtual&&accountType(contaAtual)==='gestora'?(contaAtual.pessoas??[]).reduce((sum,p)=>sum+contributionTarget(p,mes),0):[salario,...(contaAtual?.conjunta?[salario2]:[])].reduce((s,v)=>s+(v?v.liquido+v.refeicao+v.beneficio+v.adicional:0),0);
  const projetar=(prefixo:string)=>projectRecurrences(prefixo,contaId,recorrencias,registros).map(entry=>isGestora?{...entry,cartaoId:undefined,faturaMes:undefined}:entry);
  const doMes=[...registros.filter(l=>(isGestora?managementEntryMonth(l):l.data.slice(0,7))===mes),...projetar(mes)].sort((a,b)=>b.data.localeCompare(a.data)||((b.id??0)-(a.id??0)));
  const vencimentos=doMes.filter(l=>l.tipo==='despesa'&&l.status==='previsto'&&l.data<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)).sort((a,b)=>a.data.localeCompare(b.data));
  const confirmado=doMes.filter(l=>l.status==='confirmado');
  const soma=(lista:Lancamento[])=>lista.reduce((s,l)=>s+l.valorCentavos,0);
  const receitas=soma(confirmado.filter(l=>l.tipo==='receita'));
  const baseCalculada=planoTravado?.baseCentavos??(baseReceita==='atual'?soma(doMes.filter(l=>l.tipo==='receita')):salarioBase);
  const fixosDoMes=planoTravado?{totalCentavos:planoTravado.fixosCentavos,percentage:planoTravado.fixos}:monthlyFixedBudget([...registros,...projetar(mes)],baseCalculada,mes);
  const percentuais={fixos:fixosDoMes.percentage??0,variaveis:Number(percentuaisTexto.variaveis),reserva:Number(percentuaisTexto.reserva)};
  const totalPercentuais=Math.round((percentuais.fixos+percentuais.variaveis+percentuais.reserva)*100)/100;
  const distribuicaoValida=fixosDoMes.percentage!==null&&percentuaisCompletos&&Object.values(percentuais).every(n=>Number.isFinite(n)&&n>=0&&n<=100&&Math.abs(n*100-Math.round(n*100))<0.000001)&&totalPercentuais===100;
  const regras={...(planoTravado??config??{id:contaId,...vazio}),fixos:fixosDoMes.percentage??0};
  const despesas=soma(confirmado.filter(l=>l.tipo==='despesa'));
  const previstas=soma(doMes.filter(l=>l.tipo==='receita'));
  const gastoFixo=soma(confirmado.filter(l=>isMonthlyCommitment(l)));
  const gastoVariavel=soma(confirmado.filter(l=>l.tipo==='despesa'&&!isMonthlyCommitment(l)));
  const variavelTotal=planoTravado?.variaveisCentavos??Math.max(0,Math.round(baseCalculada*regras.variaveis/100));
  const distribuicaoCasal=contaAtual?.distribuicoesCasal?.find(d=>d.mes===mes);
  const variavelComum=isCasal?(distribuicaoCasal?.comumCentavos??splitSharedBudget(variavelTotal,contaAtual?.percentualPessoalCasal??5000).comum):variavelTotal;
  const saldosPessoais=contaAtual&&isCasal?personalBalances(contaAtual,`${mes}-31`):[];
  const saldoConta=registeredBalance(registros,reservas,isCasal?(contaAtual?.transferenciasPessoais??[]):[],mes);
  const ciclo=payCycleWeeks(mes,registros,variavelComum);
  const semanas=ciclo.semanas;
  const reservado=reservas.reduce((total,r)=>total+r.valorCentavos,0);
  const reservadoNoMes=reservas.filter(r=>r.data.startsWith(mes));
