  async function editar(l:Lancamento){if(l.parcial){alert('Este lançamento tem pagamentos parciais. Estorne as partes confirmadas antes de editar a previsão.');return;}if(l.gestao){alert('Este lançamento foi gerado pela Gestora. Use a seção Gestora para corrigir a compra ou remover e registrar novamente o pagamento.');return;}if(!podeEditar(l.data))return;if((l.id??0)<0){const {id:_,...dados}=l;void _;const id=await db.lancamentos.add({...dados,contaId});l={...dados,id};}setEdicao(l.id);setDescricao(l.descricao);setObservacao(l.observacao??'');setValor(String(l.valorCentavos/100));setTipo(l.tipo);setNatureza(l.natureza);setCategoria(l.categoria);setData(l.data);setStatus(l.status);setCartaoId(l.cartaoId??'');setFaturaManual(l.faturaMes??'');setRepetir(false);setErro('');setModal(true);}
