  async function salvar(e:React.FormEvent){e.preventDefault();if(!podeEditar(data))return;const centavos=paraCentavos(valor);if(repetir&&(!Number.isInteger(Number(quantidade))||Number(quantidade)<2||Number(quantidade)>60)){setErro('Informe entre 2 e 60 meses inteiros.');return;}if(!descricao.trim()||!Number.isSafeInteger(centavos)||centavos<=0){setErro('Informe descrição e valor maior que zero.');return;}if(!/^\d{4}-\d{2}-\d{2}$/.test(data)){setErro('Data inválida.');return;}setSalvando(true);setErro('');try{if(!isGestora&&tipo==='despesa'&&cartaoId&&!cartoes.some(c=>c.id===cartaoId)){setErro('Cartão não encontrado.');return;}const fixa=categoriaDefinida(categoria,tipo);const base={contaId,descricao:descricao.trim(),observacao:observacao.trim(),valorCentavos:centavos,tipo,natureza:fixa?.natureza??natureza,categoria,data,status,cartaoId:!isGestora&&tipo==='despesa'&&cartaoId?cartaoId:undefined,faturaMes:!isGestora&&tipo==='despesa'&&cartaoId?(faturaManual||invoiceMonth(data,cartoes.find(c=>c.id===cartaoId)!)):undefined};await db.transaction([db.contas,db.lancamentos,db.categorias,db.fechamentos],async tx=>{const fresh=await tx.contas.get(contaId);if(!fresh)throw Error('Conta não encontrada.');const closed=await tx.fechamentos.where('contaId').equals(contaId).toArray();if(closed.some(f=>f.mes===data.slice(0,7)))throw Error('Mês fechado.');const cat=(await tx.categorias.where('contaId').equals(contaId).toArray()).find(c=>c.tipo===tipo&&c.nome===categoria);if(!cat)throw Error('Categoria não encontrada.');base.natureza=cat.natureza;if(!isGestora&&tipo==='despesa'&&cartaoId){const card=fresh.cartoes?.find(c=>c.id===cartaoId);if(!card||(!edicao&&card.arquivado))throw Error('Cartão indisponível.');if(!faturaManual)base.faturaMes=invoiceMonth(data,card);} if(edicao){const old=await tx.lancamentos.get(edicao);if(old?.contaId!==contaId||old.gestao||old.parcial)throw Error('Este lançamento não pode ser editado aqui.');await tx.lancamentos.update(edicao,base);}else if(repetir){const grupo=crypto.randomUUID();const inicio=new Date(`${data}T12:00:00`);const dia=inicio.getDate();const itens=Array.from({length:Number(quantidade)},(_,i)=>{const y=inicio.getFullYear(),m=inicio.getMonth()+i;const ultimo=new Date(y,m+1,0).getDate();const dt=new Date(y,m,Math.min(dia,ultimo),12);return {...base,data:`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`,status:i===0?status:'previsto' as Status,grupoRecorrencia:grupo,...(base.faturaMes?{faturaMes:shiftMonth(base.faturaMes,i)}:{})};});if(itens.some(l=>closed.some(f=>f.mes===l.data.slice(0,7))))throw Error('Uma repetição cairia em mês fechado.');await tx.lancamentos.bulkAdd(itens);}else{await tx.lancamentos.add({...base,contaId});}});setModal(false);}catch(e){setErro(`Erro ao salvar: ${e instanceof Error?e.message:'tente novamente'}`);}finally{setSalvando(false);}}
  async function excluir(l:Lancamento){if(l.parcial){try{if(l.parcial.papel==='pagamento'){if(confirm(`Estornar ${moeda(l.valorCentavos)} e devolver o valor ao previsto?`))await undoPartialPayment(db,contaId,l.id!);return;}if(!confirm(`Excluir ${l.descricao}?`))return;await db.transaction([db.lancamentos,db.fechamentos],async tx=>{const fresh=await tx.lancamentos.get(l.id!);if(fresh?.contaId!==contaId||!fresh.parcial)throw Error('O lançamento foi atualizado. Reabra a lista.');await ensureOpenMonth(tx,contaId,fresh.data);await ensureOpenMonth(tx,contaId,fresh.parcial.dataPrevista);if((await tx.lancamentos.where('contaId').equals(contaId).toArray()).some(e=>e.parcial?.grupo===fresh.parcial!.grupo&&e.parcial.papel==='pagamento'))throw Error('Estorne as partes confirmadas antes de excluir o saldo previsto.');await tx.lancamentos.delete(fresh.id!);});}catch(reason){alert(reason instanceof Error?reason.message:'Não foi possível excluir.');}return;}if(l.gestao?.tipo==='compraMercado'){alert('Exclua a compra na seção Gestora para preservar os acertos vinculados.');return;}if(!podeEditar(isGestora?managementEntryMonth(l):l.data))return;if((l.id??0)<0){alert('Para remover esta previsão, exclua a recorrência na aba Recorrentes.');return;}if(l.id&&window.confirm(`Excluir ${l.descricao}?`))await db.lancamentos.delete(l.id);}

  function iniciarPagamentoParcial(l:Lancamento){setPartialTarget(l);setPartialValue('');setPartialDate(hoje());setPartialError('');setPartialNotice('');}
  async function salvarPagamentoParcial(e:React.FormEvent){e.preventDefault();if(!partialTarget||partialBusy)return;setPartialBusy(true);setPartialError('');try{const result=await recordPartialPayment(db,contaId,partialTarget,paraCentavos(partialValue),partialDate);setPartialNotice(`${partialTarget.tipo==='receita'?'Recebimento':'Pagamento'} registrado. ${result.remaining>0?`Restante previsto: ${moeda(result.remaining)}.`:'Lançamento quitado.'}`);setPartialTarget(null);}catch(reason){setPartialError(reason instanceof Error?reason.message:'Não foi possível registrar.');}finally{setPartialBusy(false);}}
  async function confirmar(l:Lancamento){if(l.parcial&&l.status==='confirmado'){try{if(l.parcial.papel==='pagamento'){if(confirm('Estornar esta parte e devolver o valor ao previsto?'))await undoPartialPayment(db,contaId,l.id!);}else await reopenPartialBalance(db,contaId,l.id!);}catch(reason){alert(reason instanceof Error?reason.message:'Não foi possível estornar.');}return;}if(l.gestao&&l.gestao.tipo!=='compraMercado'){alert('Use a seção Gestora para corrigir este pagamento.');return;}if(!podeEditar(l.data))return;if((l.id??0)<0){const {id:_,...novo}=l;void _;await db.lancamentos.add({...novo,contaId,status:'confirmado',...(novo.cartaoId&&cartoes.some(c=>c.id===novo.cartaoId)?{faturaMes:novo.faturaMes||invoiceMonth(novo.data,cartoes.find(c=>c.id===novo.cartaoId)!)}:{})});}else if(l.id)await db.lancamentos.update(l.id,{status:l.status==='previsto'?'confirmado':'previsto'});}
  async function salvarOrcamento(travar=false){if(!distribuicaoValida){alert(fixosDoMes.percentage===null?'Informe uma base de renda maior que zero para calcular o percentual fixo.':'Preencha os percentuais de variáveis e reserva com até duas casas decimais. A distribuição deve somar 100%.');return;}try{await saveMonthlyBudget(db,contaId,mes,{baseReceita,...percentuais},{base:baseCalculada,fixed:fixosDoMes.totalCentavos},travar);alert(travar?'Planejamento do mês travado. Novas entradas não alteram os valores planejados.':'Distribuição salva!');}catch(reason){alert(reason instanceof Error?reason.message:'Não foi possível salvar.');}}
